import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isRecord(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && keys.every(key => Object.hasOwn(value, key));
}

// Returns the path's segments, or null if the path is not a portable relative path.
function parsePath(value) {
  if (typeof value !== 'string' || value === '') return null;
  const segments = value.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) return null;
    if (DEVICE_STEM.test(segment.split('.')[0])) return null;
  }
  return segments;
}

function parseManifest(manifest) {
  if (!isRecord(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest must contain exactly writes and deletes');
  }
  const { writes, deletes } = manifest;
  if (!Array.isArray(writes) || !Array.isArray(deletes)) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest writes and deletes must be arrays');
  }

  const writeItems = [];
  for (let i = 0; i < writes.length; i++) {
    const item = writes[i];
    if (!isRecord(item) || !hasExactKeys(item, ['path', 'content'])) {
      throw fail('ERR_INVALID_MANIFEST', 'Write must contain exactly path and content');
    }
    const { path: relative, content } = item;
    if (typeof relative !== 'string' || typeof content !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Write path and content must be strings');
    }
    writeItems.push({ path: relative, content });
  }

  const deleteItems = [];
  for (let i = 0; i < deletes.length; i++) {
    const relative = deletes[i];
    if (typeof relative !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Delete must be a path string');
    }
    deleteItems.push(relative);
  }

  const targets = [];
  for (const relative of [...writeItems.map(item => item.path), ...deleteItems]) {
    const segments = parsePath(relative);
    if (segments === null) throw fail('ERR_INVALID_PATH', `Invalid path: ${relative}`);
    targets.push({ relative, segments });
  }

  const seen = new Set(targets.map(target => target.relative));
  if (seen.size !== targets.length) {
    throw fail('ERR_INVALID_MANIFEST', 'Duplicate manifest target');
  }
  for (const { segments } of targets) {
    for (let depth = 1; depth < segments.length; depth++) {
      if (seen.has(segments.slice(0, depth).join('/'))) {
        throw fail('ERR_INVALID_MANIFEST', 'Manifest target is an ancestor of another target');
      }
    }
  }

  return { writes: writeItems, deletes: deleteItems, targets };
}

function parseGrants(grants) {
  if (!Array.isArray(grants)) throw fail('ERR_INVALID_GRANT', 'Grants must be an array');
  const approved = new Set();
  for (let i = 0; i < grants.length; i++) {
    const grant = grants[i];
    if (!isRecord(grant) || !hasExactKeys(grant, ['path', 'operation'])) {
      throw fail('ERR_INVALID_GRANT', 'Grant must contain exactly path and operation');
    }
    const { path: relative, operation } = grant;
    if (!OPERATIONS.has(operation) || parsePath(relative) === null) {
      throw fail('ERR_INVALID_GRANT', 'Invalid grant');
    }
    approved.add(`${operation}\0${relative}`);
  }
  return approved;
}

async function lstatOrNull(target) {
  try {
    return await fs.lstat(target);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function preflightTarget(directory, segments) {
  let current = directory;
  for (let depth = 0; depth < segments.length; depth++) {
    current = path.join(current, segments[depth]);
    const stats = await lstatOrNull(current);
    if (stats === null) return; // Everything below an absent component is absent.
    const isLeaf = depth === segments.length - 1;
    if (stats.isSymbolicLink() || !(isLeaf ? stats.isFile() : stats.isDirectory())) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target: ${segments.join('/')}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  const request = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const item of request.writes) {
    if (!approved.has(`write\0${item.path}`)) {
      throw fail('ERR_DENIED', `Write not approved: ${item.path}`);
    }
  }
  for (const relative of request.deletes) {
    if (!approved.has(`delete\0${relative}`)) {
      throw fail('ERR_DENIED', `Delete not approved: ${relative}`);
    }
  }

  const root = await fs.lstat(directory);
  if (root.isSymbolicLink() || !root.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Root must be a real directory');
  }
  for (const { segments } of request.targets) {
    await preflightTarget(directory, segments);
  }

  const written = [];
  for (const item of request.writes) {
    const target = path.join(directory, ...item.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, item.content, 'utf8');
    written.push(item.path);
  }

  const deleted = [];
  for (const relative of request.deletes) {
    try {
      await fs.unlink(path.join(directory, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }

  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, fn, code) {
  try { const r = await fn(); results.push([name, code ? `FAIL resolved ${JSON.stringify(r)}` : `ok ${JSON.stringify(r)}`]); }
  catch (e) { results.push([name, e.code === code ? `ok ${code}` : `FAIL ${e.code} ${e.message}`]); }
}
const tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
const root = path.join(tmp, 'root'); const outside = path.join(tmp, 'outside');
await fs.mkdir(root); await fs.mkdir(outside);
await fs.writeFile(path.join(root, '.hidden'), 'h');
await fs.writeFile(path.join(root, 'keep.txt'), 'k');
await fs.mkdir(path.join(root, 'dir'));
await fs.writeFile(path.join(outside, 'secret.txt'), 's');
await fs.symlink(outside, path.join(root, 'junc'), 'junction');
await fs.mkdir(path.join(root, 'inner'));
await fs.symlink(path.join(root, 'inner'), path.join(root, 'injunc'), 'junction');
let fileLink = true;
try { await fs.symlink(path.join(root, 'keep.txt'), path.join(root, 'flink.txt'), 'file'); } catch { fileLink = false; }

const w = (p, c = 'x') => ({ path: p, content: c });
const g = (p, operation = 'write') => ({ path: p, operation });
await expect('approved flag', () => restore(root, { writes: [w('a.txt')], deletes: [], approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('extra write key', () => restore(root, { writes: [{ ...w('a.txt'), replace: true }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expect('missing deletes', () => restore(root, { writes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('non-string content', () => restore(root, { writes: [{ path: 'a.txt', content: 1 }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expect('dup', () => restore(root, { writes: [w('a.txt')], deletes: ['a.txt'] }, [g('a.txt'), g('a.txt', 'delete')]), 'ERR_INVALID_MANIFEST');
await expect('ancestor', () => restore(root, { writes: [w('a'), w('a/b.txt')], deletes: [] }, [g('a'), g('a/b.txt')]), 'ERR_INVALID_MANIFEST');
for (const p of ['/a', '../a', 'a/../b', './a', 'a//b', 'a\\b', 'c:x', 'A.txt', 'con', 'nul.txt', 'com1.tar.gz', 'lpt9', 'a/', '']) {
  await expect(`path ${JSON.stringify(p)}`, () => restore(root, { writes: [w(p)], deletes: [] }, []), 'ERR_INVALID_PATH');
}
await expect('com0 ok', () => restore(root, { writes: [w('com0.txt')], deletes: [] }, [g('com0.txt')]));
await expect('bad grant op', () => restore(root, { writes: [], deletes: [] }, [g('a.txt', 'read')]), 'ERR_INVALID_GRANT');
await expect('bad grant path', () => restore(root, { writes: [], deletes: [] }, [g('../a.txt')]), 'ERR_INVALID_GRANT');
await expect('grant not array', () => restore(root, { writes: [], deletes: [] }, null), 'ERR_INVALID_GRANT');
await expect('prefix grant denied', () => restore(root, { writes: [w('notes/a.txt')], deletes: [] }, [g('notes')]), 'ERR_DENIED');
await expect('wrong op denied', () => restore(root, { writes: [], deletes: ['keep.txt'] }, [g('keep.txt', 'write')]), 'ERR_DENIED');
await expect('denied no mkdir', () => restore(root, { writes: [w('ok/a.txt'), w('nope/b.txt')], deletes: [] }, [g('ok/a.txt')]), 'ERR_DENIED');
await expect('junction parent', () => restore(root, { writes: [w('new/a.txt'), w('junc/secret.txt', 'pwn')], deletes: [] }, [g('new/a.txt'), g('junc/secret.txt')]), 'ERR_UNSAFE_TARGET');
await expect('inside junction', () => restore(root, { writes: [], deletes: ['injunc/x.txt'] }, [g('injunc/x.txt', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('junction leaf delete', () => restore(root, { writes: [], deletes: ['junc'] }, [g('junc', 'delete')]), 'ERR_UNSAFE_TARGET');
if (fileLink) await expect('file symlink', () => restore(root, { writes: [w('flink.txt')], deletes: [] }, [g('flink.txt')]), 'ERR_UNSAFE_TARGET');
await expect('dir target', () => restore(root, { writes: [], deletes: ['dir'] }, [g('dir', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('file as parent', () => restore(root, { writes: [w('keep.txt/a')], deletes: [] }, [g('keep.txt/a')]), 'ERR_UNSAFE_TARGET');
await expect('empty', () => restore(root, { writes: [], deletes: [] }, []));
await expect('happy', () => restore(root, { writes: [w('keep.txt', 'new'), w('deep/x/y.txt')], deletes: ['com0.txt', 'missing.txt'] },
  [g('keep.txt'), g('keep.txt'), g('deep/x/y.txt'), g('com0.txt', 'delete'), g('missing.txt', 'delete')]));
for (const r of results) console.log(r[1].startsWith('ok') ? 'PASS' : 'FAIL', r[0], r[1]);
console.log('fileLink', fileLink, 'root entries', (await fs.readdir(root)).sort().join(','));
